{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "In non-human primates, oral evobrutinib (the query molecule) was detected in CSF at pharmacologically relevant doses, directly demonstrating meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ibrutinib, a close BTK-inhibitor analogue sharing the acrylamide-piperidine and 4-phenoxyphenyl motifs, showed a protein-binding-corrected CSF/plasma ratio of 28.7% in humans, indicating significant CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A related BTK inhibitor (Compound 10) achieved an acceptable Kp,uu of 0.37 in a rat constant-infusion study, supporting meaningful brain exposure for this inhibitor class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "In healthy humans, AMG 579, a piperidine-pyridine-phenoxy amide, had CSF concentrations below 5% of plasma, showing that some molecules in this broad scaffold can have poor CNS access; its lower similarity limits transfer to evobrutinib.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: direct NHP CSF detection of evobrutinib plus consistent brain-penetration data from close BTK inhibitor analogues (ibrutinib, Compound 10) outweigh the single low-CSF example from a more distant molecule.",
  "evidence_gaps": [
    "No quantitative Kp,uu or human CSF/plasma ratio for evobrutinib itself; C11 is qualitative CSF detection in NHP.",
    "Efflux-transporter phenotype of evobrutinib is not directly measured; most quantitative data come from close analogues.",
    "Human CNS efficacy data for evobrutinib are not included in the provided evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

